pub(crate) fn of_alnum(cp: i32) -> i32 {
    let mut lo: i32 = 0;
    let mut hi: i32 = 789;
    let mut mid: i32 = 0;
    while lo < hi {
        mid = (lo + hi) / 2;
        if cp < OF_ALNUMS[(mid * 2 + 0) as usize] {
            hi = mid;
        } else if cp > OF_ALNUMS[(mid * 2 + 1) as usize] {
            lo = mid + 1;
        } else {
            return 1;
        }
    }
    return 0;
}
pub fn of_eligible(words: &mut crate::port::Cells, text: &mut crate::port::Cells, w: i32) -> i32 {
    let s: i32 = ow_get(words, w, hd_tstart());
    let n: i32 = ow_get(words, w, hd_tlen());
    let mut i: i32 = 0;
    if (s < 0) || ((n <= 0) || (n > (crate::port::cells_len(text) - s))) {
        return 0;
    }
    if (ow_get(words, w, owf_flags()) & oe_garbage()) != 0 {
        return 0;
    }
    while i < n {
        if of_alnum(crate::port::cells_at(text, s + i)) == 1 {
            return 1;
        }
        i += 1;
    }
    return 0;
}
pub(crate) fn of_pass(pass: i32) -> i32 {
    if (pass == op_first()) || ((pass == op_upscaled()) || ((pass == op_body_ink()) || ((pass == op_receipt()) || ((pass == op_receipt_rescue()) || ((pass == op_line()) || (pass == op_cell())))))) {
        return 1;
    }
    return 0;
}
pub(crate) fn of_full(pass: i32) -> i32 {
    if (pass == op_line()) || (pass == op_cell()) {
        return 0;
    }
    return of_pass(pass);
}
pub(crate) fn of_reading_same(words: &mut crate::port::Cells, text: &mut crate::port::Cells, refs: &mut crate::port::Cells, a: i32, b: i32, n: i32) -> i32 {
    let mut i: i32 = 0;
    let mut f: i32 = 0;
    let mut wa: i32 = 0;
    let mut wb: i32 = 0;
    while i < n {
        wa = crate::port::cells_at(refs, a + i);
        wb = crate::port::cells_at(refs, b + i);
        if of_word_same(words, text, wa, wb, 0) == 0 {
            return 0;
        }
        f = hd_x0();
        while f <= hd_y1() {
            if ((ow_get(words, wa, f) + 5) / 10) != ((ow_get(words, wb, f) + 5) / 10) {
                return 0;
            }
            f += 1;
        }
        i += 1;
    }
    return 1;
}
pub fn of_readings(runs: &mut crate::port::Cells, words: &mut crate::port::Cells, text: &mut crate::port::Cells, page: i32, mut reads: &mut crate::port::Cells, mut refs: &mut crate::port::Cells) -> i32 {
    // Deduplicate eligible readings by exact source text and tenth-point boxes; confidence alone is not an independent vote. Keep the earliest recorded run.
    let mut r: i32 = 0;
    let mut w: i32 = 0;
    let mut end: i32 = 0;
    let mut start: i32 = 0;
    let mut n: i32 = 0;
    let mut k: i32 = 0;
    let mut duplicate: i32 = 0;
    crate::port::cells_drop(reads, 0);
    crate::port::cells_drop(refs, 0);
    while r < or_count(runs) {
        if (or_get(runs, r, orf_page()) == page) && (of_pass(or_get(runs, r, orf_pass())) == 1) {
            start = crate::port::cells_len(refs);
            w = or_get(runs, r, orf_wfirst());
            end = w + or_get(runs, r, orf_wcount());
            while w < end {
                if of_eligible(words, text, w) == 1 {
                    crate::port::cells_push(refs, w);
                }
                w += 1;
            }
            n = crate::port::cells_len(refs) - start;
            k = 0;
            duplicate = 0;
            while (k < crate::port::cells_len(reads)) && (duplicate == 0) {
                if n == crate::port::cells_at(reads, k + 2) {
                    duplicate = of_reading_same(words, text, refs, start, crate::port::cells_at(reads, k + 1), n);
                }
                k += 3;
            }
            if (n > 0) && (duplicate == 0) {
                crate::port::cells_push(reads, r);
                crate::port::cells_push(reads, start);
                crate::port::cells_push(reads, n);
            } else {
                crate::port::cells_drop(refs, start);
            }
        }
        r += 1;
    }
    return crate::port::cells_len(reads) / 3;
}
pub(crate) fn of_seq_same(words: &mut crate::port::Cells, text: &mut crate::port::Cells, refs: &mut crate::port::Cells, start: i32, count: i32, seq: &mut crate::port::Cells) -> i32 {
    // Compare token sequences with preserved word boundaries, ASCII folded. A merged token is a competing candidate, never fabricated from split characters.
    let mut i: i32 = 0;
    if count != crate::port::cells_len(seq) {
        return 0;
    }
    while i < count {
        if of_word_same(words, text, crate::port::cells_at(refs, start + i), crate::port::cells_at(seq, i), 1) == 0 {
            return 0;
        }
        i += 1;
    }
    return 1;
}
pub(crate) fn of_add_candidate(words: &mut crate::port::Cells, text: &mut crate::port::Cells, run: i32, seq: &mut crate::port::Cells, mut c: &mut crate::port::Cells, mut refs: &mut crate::port::Cells) -> i32 {
    let n: i32 = crate::port::cells_len(seq);
    let r: i32 = crate::port::cells_len(c) / of_cstride();
    let mut i: i32 = 0;
    let mut w: i32 = 0;
    let mut cp: i32 = 0;
    let mut j: i32 = 0;
    let mut sum: i64 = 0 as i64;
    let mut dictionary: i32 = 1;
    let mut valid: i32 = 1;
    let mut numeric: i32 = 0;
    crate::port::cells_push(c, run);
    crate::port::cells_push(c, crate::port::cells_len(refs));
    crate::port::cells_push(c, n);
    crate::port::cells_push(c, 0);
    while i < n {
        w = crate::port::cells_at(seq, i);
        crate::port::cells_push(refs, w);
        sum += ow_get(words, w, hd_conf()) as i64;
        if (ow_get(words, w, owf_flags()) & oe_dictionary()) == 0 {
            dictionary = 0;
        }
        if ofmt_valid(text, ow_get(words, w, hd_tstart()), ow_get(words, w, hd_tlen())) == 0 {
            valid = 0;
        }
        j = 0;
        while j < ow_get(words, w, hd_tlen()) {
            cp = crate::port::cells_at(text, ow_get(words, w, hd_tstart()) + j);
            if fmt_digit(cp) == 1 {
                numeric = 1;
            }
            j += 1;
        }
        i += 1;
    }
    if n == 0 {
        dictionary = 0;
        valid = 0;
    }
    if n > 0 {
        crate::port::cells_push(c, (sum / (n as i64)) as i32);
    } else {
        crate::port::cells_push(c, 0);
    }
    crate::port::cells_push(c, dictionary);
    crate::port::cells_push(c, valid);
    crate::port::cells_push(c, numeric);
    return r;
}
pub fn of_candidates(words: &mut crate::port::Cells, text: &mut crate::port::Cells, rows: &mut crate::port::Cells, parents: &mut crate::port::Cells, root: i32, selected: &mut crate::port::Cells, reads: &mut crate::port::Cells, mut c: &mut crate::port::Cells, mut refs: &mut crate::port::Cells, mut seq: &mut crate::port::Cells) -> i32 {
    // Build each reading's words in recorded OCR order, aggregate sequence votes once per distinct reading. Candidate zero is the incumbent in selection order. Caller supplies de-duplicated reads and aligned rows including selected nodes.
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut k: i32 = 0;
    let mut w: i32 = 0;
    let mut found: i32 = 0;
    let mut run: i32 = 0;
    let mut previous_run: i32 = -1;
    let mut next_run: i32 = -1;
    let mut scan: i32 = 0;
    let mut candidate: i32 = 0;
    let mut added: i32 = 0;
    let mut candidate_votes: i32 = 0;
    let mut sum: i64 = 0 as i64;
    let mut confidence: i32 = 0;
    crate::port::cells_drop(c, 0);
    crate::port::cells_drop(refs, 0);
    crate::port::cells_drop(seq, 0);
    while i < crate::port::cells_len(selected) {
        w = crate::port::cells_at(selected, i);
        j = 0;
        found = 0;
        while (j < crate::port::cells_len(rows)) && (found == 0) {
            if (crate::port::cells_at(rows, j) == w) && (of_root(parents, j) == root) {
                found = 1;
            }
            j += 1;
        }
        if found == 1 {
            crate::port::cells_push(seq, w);
        }
        i += 1;
    }
    of_add_candidate(words, text, -1, seq, c, refs);
    i = 0;
    while i < crate::port::cells_len(reads) {
        next_run = -1;
        scan = 0;
        while scan < crate::port::cells_len(reads) {
            run = crate::port::cells_at(reads, scan);
            if (run > previous_run) && ((next_run < 0) || (run < next_run)) {
                next_run = run;
            }
            scan += 3;
        }
        run = next_run;
        previous_run = run;
        crate::port::cells_drop(seq, 0);
        j = 0;
        while j < crate::port::cells_len(rows) {
            w = crate::port::cells_at(rows, j);
            if (of_root(parents, j) == root) && (ow_get(words, w, owf_run()) == run) {
                k = 0;
                while (k < crate::port::cells_len(seq)) && (crate::port::cells_at(seq, k) < w) {
                    k += 1;
                }
                if (k == crate::port::cells_len(seq)) || (crate::port::cells_at(seq, k) != w) {
                    crate::port::cells_push(seq, w);
                    added = crate::port::cells_len(seq) - 1;
                    while added > k {
                        crate::port::cells_set(seq, added, crate::port::cells_at(seq, added - 1));
                        added -= 1;
                    }
                    crate::port::cells_set(seq, k, w);
                }
            }
            j += 1;
        }
        if crate::port::cells_len(seq) > 0 {
            candidate = 0;
            found = -1;
            while (candidate < (crate::port::cells_len(c) / of_cstride())) && (found < 0) {
                if of_seq_same(words, text, refs, of_cget(c, candidate, 1), of_cget(c, candidate, 2), seq) == 1 {
                    found = candidate;
                }
                candidate += 1;
            }
            if found < 0 {
                found = of_add_candidate(words, text, run, seq, c, refs);
            }
            candidate_votes = of_cget(c, found, 3) + 1;
            crate::port::cells_set(c, (found * of_cstride()) + 3, candidate_votes);
            sum = 0 as i64;
            j = 0;
            while j < crate::port::cells_len(seq) {
                sum += ow_get(words, crate::port::cells_at(seq, j), hd_conf()) as i64;
                j += 1;
            }
            confidence = (sum / (crate::port::cells_len(seq) as i64)) as i32;
            if confidence > of_cget(c, found, 4) {
                crate::port::cells_set(c, (found * of_cstride()) + 4, confidence);
            }
        }
        i += 3;
    }
    return crate::port::cells_len(c) / of_cstride();
}
pub fn of_choice(c: &mut crate::port::Cells, incumbent_count: i32) -> i32 {
    let mut i: i32 = 1;
    let mut numeric: i32 = 0;
    let mut best: i32 = -1;
    let mut rule: i32 = 0;
    let mut incumbent: i32 = 0;
    if incumbent_count > of_slot_max() {
        return -1;
    }
    if crate::port::cells_len(c) < of_cstride() {
        return -1;
    }
    i = 0;
    while i < (crate::port::cells_len(c) / of_cstride()) {
        if of_cget(c, i, 7) == 1 {
            numeric = 1;
        }
        i += 1;
    }
    if incumbent_count > 0 {
        incumbent = 1;
    }
    i = 1;
    while i < (crate::port::cells_len(c) / of_cstride()) {
        rule = of_rule(incumbent, numeric, of_cget(c, 0, 6), of_cget(c, i, 6), of_cget(c, i, 5), of_cget(c, i, 3), of_cget(c, 0, 3), of_cget(c, i, 4), of_cget(c, 0, 4));
        if (of_cget(c, i, 2) > 0) && ((rule > 0) && (rule < 4)) {
            if best < 0 {
                best = i;
            } else if (of_cget(c, i, 3) > of_cget(c, best, 3)) || ((of_cget(c, i, 3) == of_cget(c, best, 3)) && ((of_cget(c, i, 4) > of_cget(c, best, 4)) || ((of_cget(c, i, 4) == of_cget(c, best, 4)) && (of_cget(c, i, 0) < of_cget(c, best, 0))))) {
                best = i;
            }
        }
        i += 1;
    }
    return best;
}
pub fn of_null_votes(runs: &mut crate::port::Cells, words: &mut crate::port::Cells, reads: &mut crate::port::Cells, rows: &mut crate::port::Cells, parents: &mut crate::port::Cells, root: i32) -> i32 {
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut found: i32 = 0;
    let mut count: i32 = 0;
    let mut run: i32 = 0;
    while i < crate::port::cells_len(reads) {
        run = crate::port::cells_at(reads, i);
        if of_full(or_get(runs, run, orf_pass())) == 1 {
            j = 0;
            found = 0;
            while (j < crate::port::cells_len(rows)) && (found == 0) {
                if (of_root(parents, j) == root) && (ow_get(words, crate::port::cells_at(rows, j), owf_run()) == run) {
                    found = 1;
                }
                j += 1;
            }
            if found == 0 {
                count += 1;
            }
        }
        i += 3;
    }
    return count;
}
